def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full-height divider.
    divider = None
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            divider = c
            break
    if divider is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r in range(h):
        cells = [(c, grid[r][c]) for c in range(divider) if grid[r][c] != 0]
        if not cells:
            continue

        # Use the contiguous nonzero object closest to the divider.
        end = cells[-1][0]
        start = end
        while start > 0 and grid[r][start - 1] != 0:
            start -= 1
        segment = grid[r][start:end + 1]
        color = grid[r][end]
        length = len(segment)

        # A distinct one-cell endpoint acts as a solid-color marker.
        marker = (length > 1 and segment[-1] != segment[-2])
        for c in range(divider + 1, w):
            if marker or (c - divider - 1) % length == 0:
                out[r][c] = color

    return out
